package filetree

import (
	"os"
	"path/filepath"
	"strings"

	"paper-scan-processor/backend/pdf"
)

// LocalFile describes one local file discovered by ScanLocalRoot. Not every
// file is a PDF — non-PDF files (e.g. image scans) are included too, with
// IsPDF false and PageCount 0.
type LocalFile struct {
	Path      string `json:"path"`
	Name      string `json:"name"` // filename including extension
	SizeBytes int64  `json:"sizeBytes"`
	IsPDF     bool   `json:"isPdf"`
	PageCount int    `json:"pageCount"` // only meaningful when IsPDF is true
	Corrupt   bool   `json:"corrupt"`   // IsPDF true but its page count could not be read
}

// LocalFileGroup is one folder's worth of files, plus its nested
// subfolders. Name is "" only for the root LocalFileGroup returned by
// ScanLocalRoot; every subgroup has a real folder name.
type LocalFileGroup struct {
	Name      string           `json:"name"`
	Files     []LocalFile      `json:"files"`
	Subgroups []LocalFileGroup `json:"subgroups"`
}

// ScanLocalRoot scans root recursively and returns it as a LocalFileGroup:
// its own direct files in Files, and every subdirectory (at any depth) as a
// nested Subgroups entry. Unlike a subfolder, the root is always returned
// even if it's entirely empty, so the UI has something to render a "no
// files" state from.
func ScanLocalRoot(root string) (LocalFileGroup, error) {
	return scanDirectory(root, "")
}

// scanDirectory scans dir's direct entries in a single pass: each file
// becomes a LocalFile, each non-hidden subdirectory is scanned recursively
// (skipping symlinks) and — if its subtree contains no files at all — is
// omitted from Subgroups. name is used as the returned group's Name (pass ""
// for the scan root). PDFs whose page count can't be read are still
// included, flagged via LocalFile.Corrupt, rather than dropped from the
// scan; non-PDF files are never considered corrupt.
//
// Both slice fields are always initialized to non-nil (even when empty),
// since a nil Go slice marshals to JSON `null` rather than `[]`, which
// crashes the frontend (e.g. `group.subgroups.length` throws on null).
func scanDirectory(dir, name string) (LocalFileGroup, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return LocalFileGroup{}, err
	}

	files := []LocalFile{}
	subgroups := []LocalFileGroup{}

	for _, e := range entries {
		entryName := e.Name()
		if strings.HasPrefix(entryName, ".") {
			continue
		}

		if e.IsDir() {
			// os.DirEntry.IsDir() reflects the directory entry itself rather
			// than a resolved symlink target, so a symlinked directory
			// (including one that would otherwise form a loop) never enters
			// this branch — it's simply skipped.
			sub, err := scanDirectory(filepath.Join(dir, entryName), entryName)
			if err != nil {
				return LocalFileGroup{}, err
			}
			if len(sub.Files) > 0 || len(sub.Subgroups) > 0 {
				subgroups = append(subgroups, sub)
			}
			continue
		}

		path := filepath.Join(dir, entryName)
		info, err := os.Stat(path)
		if err != nil {
			continue
		}

		isPDF := strings.HasSuffix(strings.ToLower(entryName), ".pdf")
		var count int
		var corrupt bool
		if isPDF {
			count, err = pdf.PageCount(path)
			corrupt = err != nil
		}
		files = append(files, LocalFile{
			Path:      path,
			Name:      entryName,
			SizeBytes: info.Size(),
			IsPDF:     isPDF,
			PageCount: count,
			Corrupt:   corrupt,
		})
	}

	return LocalFileGroup{Name: name, Files: files, Subgroups: subgroups}, nil
}

import { describe, it, expect, vi } from 'vitest'
import { act, renderHook, waitFor } from '@testing-library/react'
import { useFileTree, flattenFiles } from './useFileTree'
import { LocalFileGroup } from '../types'
import { PickFolder, ScanLocalRoot } from '../../../../wailsjs/go/main/App'

vi.mock('../../../../wailsjs/go/main/App', () => ({
  PickFolder: vi.fn(),
  ScanLocalRoot: vi.fn(),
}))

function file(path: string) {
  return { path, name: path, sizeBytes: 0, isPdf: true, pageCount: 1, corrupt: false }
}

describe('flattenFiles', () => {
  it("lists a group's own files before its subgroups, recursively", () => {
    const tree: LocalFileGroup = {
      name: '',
      files: [file('/root/misc.pdf')],
      subgroups: [
        {
          name: 'invoices',
          files: [file('/root/invoices/a.pdf')],
          subgroups: [
            { name: 'nested', files: [file('/root/invoices/nested/c.pdf')], subgroups: [] },
          ],
        },
        { name: 'receipts', files: [file('/root/receipts/b.pdf')], subgroups: [] },
      ],
    }

    expect(flattenFiles(tree).map(f => f.path)).toEqual([
      '/root/misc.pdf',
      '/root/invoices/a.pdf',
      '/root/invoices/nested/c.pdf',
      '/root/receipts/b.pdf',
    ])
  })
})

describe('useFileTree', () => {
  it('starts with no root and no tree', () => {
    const { result } = renderHook(() => useFileTree())
    expect(result.current.root).toBeNull()
    expect(result.current.tree).toBeNull()
    expect(result.current.loading).toBe(false)
    expect(result.current.error).toBeNull()
  })

  it('does nothing when the folder picker is cancelled', async () => {
    vi.mocked(PickFolder).mockResolvedValueOnce('')
    const { result } = renderHook(() => useFileTree())
    await act(async () => { await result.current.pickRoot() })
    expect(result.current.root).toBeNull()
    expect(ScanLocalRoot).not.toHaveBeenCalled()
  })

  it('scans the chosen root and stores the resulting tree', async () => {
    vi.mocked(PickFolder).mockResolvedValueOnce('/output/batch')
    const tree = {
      name: '',
      files: [],
      subgroups: [{ name: 'invoices', files: [{ path: '/output/batch/invoices/a.pdf', name: 'a', sizeBytes: 100, pageCount: 2, corrupt: false }], subgroups: [] }],
    }
    vi.mocked(ScanLocalRoot).mockResolvedValueOnce(tree as any)

    const { result } = renderHook(() => useFileTree())
    await act(async () => { await result.current.pickRoot() })

    expect(result.current.root).toBe('/output/batch')
    expect(result.current.tree).toEqual(tree)
    expect(result.current.loading).toBe(false)
    expect(result.current.error).toBeNull()
  })

  it('sets an error and clears the tree when the scan fails', async () => {
    vi.mocked(PickFolder).mockResolvedValueOnce('/output/batch')
    vi.mocked(ScanLocalRoot).mockRejectedValueOnce(new Error('permission denied'))

    const { result } = renderHook(() => useFileTree())
    await act(async () => { await result.current.pickRoot() })

    await waitFor(() => expect(result.current.error).toContain('permission denied'))
    expect(result.current.tree).toBeNull()
    expect(result.current.loading).toBe(false)
  })
})

import { describe, it, expect } from 'vitest'
import { resolveEffectiveAssignments } from './useDriveAssignments'
import { LocalFileGroup, DriveAssignment } from '../types'

function file(path: string) {
  return { path, name: path, sizeBytes: 0, isPdf: true, pageCount: 1, corrupt: false }
}

function folder(path: string): DriveAssignment {
  return { driveFolderId: path, path }
}

const TREE: LocalFileGroup = {
  name: '',
  files: [file('/root/misc.pdf')],
  subgroups: [
    {
      name: 'invoices',
      files: [file('/root/invoices/a.pdf')],
      subgroups: [
        { name: 'nested', files: [file('/root/invoices/nested/b.pdf')], subgroups: [] },
      ],
    },
  ],
}

describe('resolveEffectiveAssignments', () => {
  it('resolves nothing when no assignments have been made', () => {
    const result = resolveEffectiveAssignments(TREE, { groupAssignments: new Map(), fileOverrides: new Map() })
    expect(result.get('/root/misc.pdf')).toBeNull()
    expect(result.get('/root/invoices/a.pdf')).toBeNull()
    expect(result.get('/root/invoices/nested/b.pdf')).toBeNull()
  })

  it('a root-level file has no group to inherit from', () => {
    const groupAssignments = new Map([['invoices', folder('/Finance')]])
    const result = resolveEffectiveAssignments(TREE, { groupAssignments, fileOverrides: new Map() })
    expect(result.get('/root/misc.pdf')).toBeNull()
  })

  it('a group assignment is inherited by its files and nested subgroups', () => {
    const groupAssignments = new Map([['invoices', folder('/Finance')]])
    const result = resolveEffectiveAssignments(TREE, { groupAssignments, fileOverrides: new Map() })
    expect(result.get('/root/invoices/a.pdf')).toEqual(folder('/Finance'))
    expect(result.get('/root/invoices/nested/b.pdf')).toEqual(folder('/Finance'))
  })

  it('a nested subgroup assignment overrides the ancestor group for its own files', () => {
    const groupAssignments = new Map([
      ['invoices', folder('/Finance')],
      ['invoices/nested', folder('/Finance/Nested')],
    ])
    const result = resolveEffectiveAssignments(TREE, { groupAssignments, fileOverrides: new Map() })
    expect(result.get('/root/invoices/a.pdf')).toEqual(folder('/Finance'))
    expect(result.get('/root/invoices/nested/b.pdf')).toEqual(folder('/Finance/Nested'))
  })

  it('a file override wins over its group assignment', () => {
    const groupAssignments = new Map([['invoices', folder('/Finance')]])
    const fileOverrides = new Map([['/root/invoices/a.pdf', folder('/Special')]])
    const result = resolveEffectiveAssignments(TREE, { groupAssignments, fileOverrides })
    expect(result.get('/root/invoices/a.pdf')).toEqual(folder('/Special'))
    expect(result.get('/root/invoices/nested/b.pdf')).toEqual(folder('/Finance'))
  })
})

import { describe, it, expect } from 'vitest'
import { pruneSelectionForAssignment } from './pruneSelection'
import { LocalFileGroup } from './types'

function file(path: string) {
  return { path, name: path, sizeBytes: 0, isPdf: true, pageCount: 1, corrupt: false }
}

const TREE: LocalFileGroup = {
  name: '',
  files: [file('/root/misc.pdf')],
  subgroups: [
    {
      name: 'invoices',
      files: [file('/root/invoices/a.pdf'), file('/root/invoices/b.pdf')],
      subgroups: [
        { name: 'nested', files: [file('/root/invoices/nested/c.pdf')], subgroups: [] },
      ],
    },
    { name: 'receipts', files: [file('/root/receipts/d.pdf')], subgroups: [] },
  ],
}

describe('pruneSelectionForAssignment', () => {
  it('keeps a selection with no ancestor/descendant relationships untouched', () => {
    const items = [
      { type: 'file' as const, path: '/root/misc.pdf' },
      { type: 'group' as const, key: 'receipts' },
    ]
    expect(pruneSelectionForAssignment(TREE, items)).toEqual(expect.arrayContaining(items))
    expect(pruneSelectionForAssignment(TREE, items).length).toBe(2)
  })

  it('drops a file that is a descendant of a selected group', () => {
    const items = [
      { type: 'group' as const, key: 'invoices' },
      { type: 'file' as const, path: '/root/invoices/a.pdf' },
    ]
    expect(pruneSelectionForAssignment(TREE, items)).toEqual([{ type: 'group', key: 'invoices' }])
  })

  it('drops a subgroup that is a descendant of a selected ancestor group', () => {
    const items = [
      { type: 'group' as const, key: 'invoices' },
      { type: 'group' as const, key: 'invoices/nested' },
    ]
    expect(pruneSelectionForAssignment(TREE, items)).toEqual([{ type: 'group', key: 'invoices' }])
  })

  it('drops a file nested two levels below a selected ancestor group', () => {
    const items = [
      { type: 'group' as const, key: 'invoices' },
      { type: 'file' as const, path: '/root/invoices/nested/c.pdf' },
    ]
    expect(pruneSelectionForAssignment(TREE, items)).toEqual([{ type: 'group', key: 'invoices' }])
  })

  it('keeps a file selected alongside its sibling group, since it is not that group\'s descendant', () => {
    const items = [
      { type: 'group' as const, key: 'invoices' },
      { type: 'file' as const, path: '/root/receipts/d.pdf' },
    ]
    expect(pruneSelectionForAssignment(TREE, items)).toEqual(expect.arrayContaining(items))
    expect(pruneSelectionForAssignment(TREE, items).length).toBe(2)
  })

  it('a root-level file has no ancestor group and is never pruned', () => {
    const items = [
      { type: 'group' as const, key: 'invoices' },
      { type: 'file' as const, path: '/root/misc.pdf' },
    ]
    expect(pruneSelectionForAssignment(TREE, items)).toEqual(expect.arrayContaining(items))
    expect(pruneSelectionForAssignment(TREE, items).length).toBe(2)
  })
})

